import{z as n,x as d,o as E,c as B,q as l,j as o,D as A,d as t,s,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"WAF","description":"","frontmatter":{"title":"WAF","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/waf.md","filePath":"cs/waf.md","lastUpdated":1791413859000}'),p={name:"cs/waf.md"};function c(f,a,h,m,F,u){const r=d("Mermaid");return E(),B("div",null,[a[2]||(a[2]=l('<h1 id="waf" tabindex="-1">WAF <a class="header-anchor" href="#waf" aria-label="Permalink to &quot;WAF&quot;">​</a></h1><div class="epigraph"><p>Web 应用防火墙在应用前按规则看 HTTP。它能挡已知噪声与部分注入形态，但不是规格：编码绕过与业务逻辑它几乎看不见。把它当补偿控制，不要当根治。</p><footer>—— 据 OWASP 对 WAF；ModSecurity 核心规则集作为工程实例点名</footer></div><p>上一课<a href="/cs/credential-stuffing">撞库</a>里自动化请求已经成形；缺口是<strong>边缘过滤</strong>这一层。本课讲 WAF 能做什么、不能做什么，不写绕过配方。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>WAF 在应用之前按规则读 HTTP：正则与签名能挡教科书式的 SQL 注入与 XSS 形态，但双重编码、把载荷挪进 JSON 字段就能让它漏看；规则调得太紧又误杀正常请求，可用性受伤。正位始终是应用修复——参数化查询与输出编码；WAF 的正位是缩窗口。</p><h3 id="虚拟补丁" tabindex="-1">虚拟补丁 <a class="header-anchor" href="#虚拟补丁" aria-label="Permalink to &quot;虚拟补丁&quot;">​</a></h3><p>虚拟补丁是它的正当用法之一：N-day 公告到补丁落地之间的窗口里，先挡住已知利用路径；窗口关闭后仍要打真补丁。</p><p><span class="marginnote">「补偿控制」翻译成大白话：根治手段（修应用代码）一时做不到时，先在外围加一道能减小损失的挡板——就像治不好漏水先放个盆，但盆永远不能代替修管道。</span></p><p><span class="marginnote">CRS。禁止绕过教程。API 安全下一课：现代攻击面常在 JSON API 而非页面。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把部署做对：优先正向允许（白名单请求形状），全量日志留存供调参与取证，灰度调参压误杀。对照下一课 BOLA 提前说一句：请求「形状」完全合法但客体越权，WAF 几乎不管。</p>',12)),(E(),o(i,null,{default:A(()=>[s(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20HTTP%5B%22%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20RULE%5B%22%E7%AD%BE%E5%90%8D%E6%88%96%E6%AD%A3%E5%88%99%22%5D%0A%20%20RULE%20--%3E%20PASS%5B%22%E5%88%B0%E5%BA%94%E7%94%A8%22%5D%0A%20%20RULE%20--%3E%20LIM%5B%22%E6%BC%8F%E8%BF%87%E7%BC%96%E7%A0%81%E4%B8%8E%E9%80%BB%E8%BE%91%22%5D%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"为什么虚拟补丁重要：N-day 公告当天攻击者手里就有武器，而补丁要走测试与发布周期——一条 WAF 规则能在几小时内上线，把这段按天算的裸奔期先挡住。挡住不等于修好，窗口关闭后仍要打真补丁。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制上 WAF 只是纵深的边缘层：它看见字节形状，看不见意图与身份上下文——同一请求对 A 用户合法、对 B 越权，规则无从区分。真正的授权在应用；边缘、缓存、业务各挡各的失败模式。BOLA 下一课。",-1)),(E(),o(i,null,{default:A(()=>[s(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%E8%BF%9B%E5%85%A5%E8%BE%B9%E7%BC%98%22%5D%20--%3E%20RATE%5B%22%E9%99%90%E6%B5%81%E5%B1%82%3A%20%E6%8C%A1%E8%BF%87%E9%87%8F%E5%99%AA%E5%A3%B0%22%5D%0A%20%20RATE%20--%3E%20WF%7B%22WAF%3A%20%E5%AD%97%E8%8A%82%E5%BD%A2%E7%8A%B6%E5%8F%AF%E7%96%91%E5%90%97%3F%22%7D%0A%20%20WF%20--%20%E6%98%AF%20--%3E%20BLOCK%5B%22%E6%8B%A6%E6%88%AA%E5%B9%B6%E8%AE%B0%E5%BD%95%3A%20%E8%99%9A%E6%8B%9F%E8%A1%A5%E4%B8%81%E7%AA%97%E5%8F%A3%22%5D%0A%20%20WF%20--%20%E5%90%A6%20--%3E%20APP%5B%22%E5%BA%94%E7%94%A8%3A%20%E5%81%9A%E5%AE%A2%E4%BD%93%E7%BA%A7%E4%B8%9A%E5%8A%A1%E6%8E%88%E6%9D%83%22%5D%0A%20%20APP%20--%3E%20OK%5B%22%E6%AD%A3%E5%B8%B8%E5%93%8D%E5%BA%94%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">常见误区：以为 WAF 挡住注入就算安全。双重编码 <code>\\%2527</code>（<code>%27</code> 再编码一次）就能让按单层解码写的签名漏看——规则看得见字节形状，看不见解码后的意图；这正是上图把「业务授权」放在 WAF 之后另立一层的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写绕过配方；边界要点名：现代攻击面常在 JSON API 与 GraphQL 而非 HTML 表单，基于页面形态的规则集覆盖随之变薄。API 安全与 BOLA 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>限流之后，WAF 挡已知 HTTP 噪声。</li><li>补偿控制，不是编码替代。</li><li>看不见客体级授权。</li><li>下一课 BOLA。</li><li>出处：OWASP WAF；ModSecurity CRS。</li></ul>',5))])}const D=n(p,[["render",c]]);export{T as __pageData,D as default};
